import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.util.*;import java.math.*;import java.io.*;import java.nio.charset.StandardCharsets;class PublicExamplesTest{static String capture(Runnable action){PrintStream previous=System.out,oldErr=System.err;ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(PrintStream out=new PrintStream(bytes,true,StandardCharsets.UTF_8)){System.setOut(out);System.setErr(out);action.run();}finally{System.setOut(previous);System.setErr(oldErr);}return bytes.toString(StandardCharsets.UTF_8).replace("\r\n","\n");}@Test void wrappedGrowthPreservesRemainingFifo(){Object q=TaskBinding.queue(3);assertEquals("",capture(()->{TaskBinding.put(q,'A');TaskBinding.put(q,'B');TaskBinding.put(q,'C');assertEquals('A',TaskBinding.get(q));assertEquals('B',TaskBinding.get(q));TaskBinding.put(q,'D');TaskBinding.put(q,'E');TaskBinding.put(q,'F');assertEquals('C',TaskBinding.get(q));assertEquals('D',TaskBinding.get(q));assertEquals('E',TaskBinding.get(q));assertEquals('F',TaskBinding.get(q));}));assertEquals("Очередь пуста\n",capture(()->assertEquals('\0',TaskBinding.get(q))));}}
